  min-width: 0;
  min-height: 220px;
  padding: var(--g-spacing-2) var(--g-spacing-3) var(--g-spacing-3);
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-m);
  background: var(--g-color-base-background);
  transition: border-color 0.1s linear;
}

.markdown-field:hover {
  border-color: var(--g-color-line-generic-hover);
}

.markdown-field:focus-within {
  border-color: var(--g-color-line-generic-active);
}

.markdown-field_invalid,
.markdown-field_invalid:hover,
